use crate::cli::ListArgs;
use blit_core::admin::ls::{self, DirEntry, LocalListing};
use blit_core::display::format_bytes;
use blit_core::endpoints::{parse_endpoint_or_local, rel_path_to_string, Endpoint};
use blit_core::remote::endpoint::{RemoteEndpoint, RemotePath};
use eyre::{bail, Result};
use std::path::Path;

pub async fn run_ls(args: ListArgs) -> Result<()> {
    match parse_endpoint_or_local(&args.target) {
        Endpoint::Local(path) => list_local_path(&path, args.json),
        Endpoint::Remote(remote) => list_remote_path(remote, args.json).await,
    }
}

fn list_local_path(path: &Path, json: bool) -> Result<()> {
    let listing = ls::list_local(path)?;

    if json {
        // Pre-A.0 the JSON path emitted a single-entry vec for the
        // non-directory case and the full sorted vec for the
        // directory case. `LocalListing::into_entries` preserves
        // that shape.
        println!("{}", serde_json::to_string_pretty(&listing.into_entries())?);
        return Ok(());
    }

    match listing {
        LocalListing::Target { entry } => {
            // Single non-directory target (file, device, FIFO,
            // socket). Pre-A.0 text printed the full path here,
            // not the basename — preserved.
            println!("FILE {:>12} {}", format_bytes(entry.size), path.display());
        }
        LocalListing::Directory { entries } => {
            println!("Listing {}:", path.display());
            for entry in entries {
                if entry.is_dir {
                    println!("DIR  {:>12} {}/", "-", entry.name);
                } else {
                    println!("FILE {:>12} {}", format_bytes(entry.size), entry.name);
                }
            }
        }
    }
    Ok(())
}

async fn list_remote_path(remote: RemoteEndpoint, json: bool) -> Result<()> {
    // Smart-dispatch: bare-host targets (no module, no path) list
    // modules, matching the v6 plan's `blit list server` semantics.
    // Module/path targets fall through to the directory-listing
    // path. The explicit `blit list-modules <host>` and
    // `blit ls <host:/module/path>` commands stay available;
    // `blit list <target>` (which aliases `ls`) just routes
    // intelligently between the two. (R41-prev / Plan §2.3.)
    if matches!(remote.path, RemotePath::Discovery) {
        return crate::list_modules::list_modules_remote(remote, json).await;
    }

    let (module, rel_path) = match &remote.path {
        RemotePath::Module { module, rel_path } => (module.clone(), rel_path.clone()),
        RemotePath::Root { rel_path } => (String::new(), rel_path.clone()),
        RemotePath::Discovery => {
            // Unreachable — handled above. Kept defensive in case
            // a future RemotePath variant lands.
            bail!("listing a bare host requires `list-modules` or module/path syntax");
        }
    };

    let path_str = rel_path_to_string(&rel_path);
    let entries: Vec<DirEntry> = ls::list_remote(&remote, module.clone(), path_str.clone()).await?;

    if json {
        println!("{}", serde_json::to_string_pretty(&entries)?);
    } else if entries.is_empty() {
        println!(
            "No entries under {}:/{}",
            module,
            if path_str.is_empty() { "" } else { &path_str }
        );
    } else {
        println!(
            "Listing {}:/{}:",
            module,
            if path_str.is_empty() { "" } else { &path_str }
        );
        for entry in entries {
            let indicator = if entry.is_dir { "DIR " } else { "FILE" };
            let size_str = if entry.is_dir {
                "-".to_string()
            } else {
                format_bytes(entry.size)
            };
            println!("{} {:>12} {}", indicator, size_str, entry.name);
        }
    }

    Ok(())
}

//! `ls` — list directory entries (local filesystem or remote
//! daemon via `List` RPC).
//!
//! Moved from `crates/blit-cli/src/ls.rs` in A.0. Smart-dispatch
//! (bare-host targets → `list-modules`) stays in the CLI because
//! it's a verb-routing decision; the same decision is made
//! UI-side by the TUI's F1/F3 split.

use crate::generated::ListRequest;
use crate::remote::endpoint::RemoteEndpoint;
use eyre::{Context, Result};
use serde::Serialize;
use std::fs;
use std::path::Path;

/// One row of a directory listing. Same shape for local and
/// remote modes so the CLI's formatter doesn't care which side
/// produced it. JSON field names match the pre-A.0 `DirEntryJson`
/// shape exactly (A.0 is no-behavior-change).
#[derive(Debug, Clone, Serialize)]
pub struct DirEntry {
    pub name: String,
    pub is_dir: bool,
    pub size: u64,
    pub mtime_seconds: i64,
}

/// Outcome of `list_local`. Discriminates "target is a directory,
/// here are its contents" from "target is a single non-directory
/// (file, device, FIFO, socket, symlink); here is its stat
/// summary." Pre-A.0 the CLI used `!metadata.is_dir()` to decide
/// the second branch; doing the same in the CLI by re-checking
/// `Path::is_file()` would silently misclassify devices/FIFOs/
/// sockets as directories. Returning the discriminator lifts the
/// decision out of presentation.
#[derive(Debug, Clone)]
pub enum LocalListing {
    /// Target was a directory. Entries are sorted by path to
    /// match the pre-A.0 text layout.
    Directory { entries: Vec<DirEntry> },
    /// Target was a single non-directory. Single-entry summary,
    /// basename in `entry.name`. Pre-A.0 the CLI's text path
    /// rendered this as `FILE {size} {full path}`; that
    /// rendering is the CLI's responsibility.
    Target { entry: DirEntry },
}

impl LocalListing {
    /// Flatten into a single entry vec. Used for the CLI's `--json`
    /// output which has always emitted "one entry per target"
    /// regardless of whether the target was a directory.
    pub fn into_entries(self) -> Vec<DirEntry> {
        match self {
            LocalListing::Directory { entries } => entries,
            LocalListing::Target { entry } => vec![entry],
        }
    }
}

/// List entries under a remote `module:path`. Caller has already
/// resolved the smart-dispatch (bare host → list-modules) on its
/// own — this function assumes a real module/path target.
pub async fn list_remote(
    remote: &RemoteEndpoint,
    module: String,
    path: String,
) -> Result<Vec<DirEntry>> {
    let uri = remote.control_plane_uri();
    let mut client = crate::client::connect_with_timeout(uri.clone()).await?;
    let response = client
        .list(ListRequest { module, path })
        .await
        .map_err(|status| eyre::eyre!(status.message().to_string()))?
        .into_inner();

    Ok(response
        .entries
        .into_iter()
        .map(|info| DirEntry {
            name: info.name,
            is_dir: info.is_dir,
            size: info.size,
            mtime_seconds: info.mtime_seconds,
        })
        .collect())
}

