//! `df` — filesystem stats for a remote module.
//!
//! Moved from `crates/blit-cli/src/df.rs` as part of A.0. The CLI
//! keeps the human / JSON formatting; this module just speaks gRPC
//! and returns the structured response.

use crate::generated::FilesystemStatsRequest;
use crate::remote::RemoteEndpoint;
use eyre::Result;
use serde::Serialize;

/// Filesystem usage for a remote module. Deserialized as-is by the
/// CLI's `--json` path and rendered as a three-line block by the
/// CLI's text path. The TUI will consume this directly for the
/// F1 daemon-detail pane.
#[derive(Debug, Clone, Serialize)]
pub struct FilesystemStats {
    pub module: String,
    pub total_bytes: u64,
    pub used_bytes: u64,
    pub free_bytes: u64,
}

/// Issue the `FilesystemStats` RPC against `remote` for `module`.
/// Caller handles formatting; presenter-agnostic.
pub async fn query(remote: &RemoteEndpoint, module: String) -> Result<FilesystemStats> {
    let uri = remote.control_plane_uri();
    let mut client = crate::client::connect_with_timeout(uri.clone()).await?;

    let response = client
        .filesystem_stats(FilesystemStatsRequest { module })
        .await
        .map_err(|status| eyre::eyre!(status.message().to_string()))?
        .into_inner();

    Ok(FilesystemStats {
        module: response.module,
        total_bytes: response.total_bytes,
        used_bytes: response.used_bytes,
        free_bytes: response.free_bytes,
    })
}

use crate::cli::DfArgs;
use blit_core::admin::df;
use blit_core::display::format_bytes;
use blit_core::endpoints::{module_and_rel_path, parse_endpoint_or_local, Endpoint};
use eyre::{bail, Result};

pub async fn run_df(args: DfArgs) -> Result<()> {
    let remote = match parse_endpoint_or_local(&args.remote) {
        Endpoint::Local(path) => {
            bail!(
                "`blit df` requires a remote module (received local path: {})",
                path.display()
            );
        }
        Endpoint::Remote(remote) => remote,
    };
    let (module, _) = module_and_rel_path(&remote)?;
    let stats = df::query(&remote, module).await?;

    if args.json {
        println!("{}", serde_json::to_string_pretty(&stats)?);
    } else {
        println!("Module: {}", stats.module);
        println!(
            "Total: {} ({} bytes)",
            format_bytes(stats.total_bytes),
            stats.total_bytes
        );
        println!(
            "Used : {} ({} bytes)",
            format_bytes(stats.used_bytes),
            stats.used_bytes
        );
        println!(
            "Free : {} ({} bytes)",
            format_bytes(stats.free_bytes),
            stats.free_bytes
        );
    }

    Ok(())
}
