87 /// Resolve and classify explicit purge targets without following symlinks.
88 /// Containment is verified before even reading target metadata, then verified
89 /// again by [`execute_deletion_plan`] immediately before mutation.
90 pub fn classify_explicit_targets(
91     module_root: &Path,
92     canonical_root: &Path,
93     rel_paths: impl IntoIterator<Item = PathBuf>,
94     operation: &'static str,
95 ) -> Result<(Vec<PathBuf>, Vec<PathBuf>), DeletionError> {
96     let mut files = Vec::new();
97     let mut dirs = Vec::new();
98     for rel in rel_paths {
99         if rel.as_os_str().is_empty() || rel == Path::new(".") {
100             continue;
101         }
102         let target = module_root.join(rel);
103         crate::path_safety::verify_contained(canonical_root, &target).map_err(|source| {
104             DeletionError::Containment {
105                 operation,
106                 target: target.clone(),
107                 source,
108             }
109         })?;
110         let metadata = match std::fs::symlink_metadata(&target) {
111             Ok(metadata) => metadata,
112             Err(error) if error.kind() == std::io::ErrorKind::NotFound => continue,
113             Err(source) => {
114                 return Err(DeletionError::Filesystem {
115                     operation,
116                     action: "stat",
117                     target,
118                     source,
119                 });
120             }
121         };
122         if metadata.file_type().is_dir() {
123             dirs.push(target);
124         } else {
125             files.push(target);
126         }
127     }
128     Ok((files, dirs))
129 }
