196     let add_file = |accum: &mut HashMap<PathBuf, UsageAccum>,
197                     rel: &Path,
198                     size: u64,
199                     max_depth: Option<usize>| {
200         for (depth, prefix) in prefix_paths(rel).into_iter().enumerate() {
201             if let Some(max) = max_depth {
202                 if depth > max {
203                     break;
204                 }
205             }
206             let entry = accum.entry(prefix).or_default();
207             entry.bytes += size;
208             entry.files += 1;
209         }
210     };
211 
212     let add_dir =
213         |accum: &mut HashMap<PathBuf, UsageAccum>, rel: &Path, max_depth: Option<usize>| {
214             for (depth, prefix) in prefix_paths(rel).into_iter().enumerate() {
215                 if let Some(max) = max_depth {
216                     if depth > max {
