222             }
223         };
224 
225     let metadata = start_abs
226         .metadata()
227         .map_err(|err| io_to_status(format!("stat {}", start_abs.display()), err))?;
228 
229     if start_abs.is_file() {
230         add_file(&mut accum, &start_rel, metadata.len(), max_depth);
231     } else {
232         if start_rel != Path::new(".") {
233             add_dir(&mut accum, &start_rel, max_depth);
234         }
235         let enumerator = FileEnumerator::new(FileFilter::default());
236         enumerator
237             .enumerate_local_streaming(&start_abs, |entry| {
238                 let rel_from_root = if start_rel == Path::new(".") {
239                     entry.relative_path.clone()
240                 } else {
241                     let mut combined = start_rel.clone();
242                     if entry.relative_path != Path::new(".") {
243                         combined.push(&entry.relative_path);
244                     }
245                     combined
246                 };
247 
248                 match entry.kind {
249                     EntryKind::Directory => add_dir(&mut accum, &rel_from_root, max_depth),
250                     EntryKind::File { size } => {
251                         add_file(&mut accum, &rel_from_root, size, max_depth)
252                     }
253                     EntryKind::Symlink { .. } => {}
254                 }
255                 Ok(())
256             })
257             .map_err(|err| internal_err("disk usage enumeration failed", err))?;
258     }
