311     module_root: PathBuf,
312     start_rel: PathBuf,
313     pattern: String,
314     case_sensitive: bool,
315     include_files: bool,
316     include_dirs: bool,
317     max_results: Option<usize>,
318     sender: &FindSender,
319 ) -> Result<(), Status> {
