336     // R41-F3: `literal_separator(true)` matches POSIX shell-glob
337     // semantics — `*` does NOT cross `/`, so `foo*.csv` matches
338     // `foo-bar.csv` but NOT `foo/bar.csv`. The basename fallback
339     // below covers the common "find files with this extension at
340     // any depth" use case (`*.csv` matches both `top.csv` and
341     // `nested/x.csv` via the basename), without making `*` greedy
342     // across the whole path. Users wanting a path-component-
343     // crossing match write `**/`.
344     let matcher = if pattern.is_empty() {
345         None
346     } else {
347         let glob = globset::GlobBuilder::new(&pattern)
348             .case_insensitive(!case_sensitive)
349             .literal_separator(true)
350             .build()
351             .map_err(|e| {
352                 Status::invalid_argument(format!("invalid find --pattern glob '{pattern}': {e}"))
353             })?;
354         Some(glob.compile_matcher())
355     };
356 
357     let mut sent = 0usize;
358     let limit = max_results.filter(|&m| m > 0);
359 
360     let mut maybe_emit =
361         |rel_path: PathBuf, metadata: std::fs::Metadata, is_dir: bool| -> Result<(), Status> {
362             if let Some(limit) = limit {
363                 if sent >= limit {
364                     return Ok(());
365                 }
366             }
367             if is_dir && !include_dirs {
368                 return Ok(());
369             }
370             if !is_dir && !include_files {
