376                 // Match against the relative path AND its file-name
377                 // tail. Users typically write `--pattern '*.txt'`
378                 // expecting it to match any file with that
379                 // extension regardless of depth. With
380                 // `literal_separator(false)` `*.txt` matches across
381                 // directory components, but matching against the
382                 // basename too is the intuitive fallback for
383                 // patterns that don't use `**`.
384                 let basename = std::path::Path::new(&rel_display)
385                     .file_name()
386                     .and_then(|s| s.to_str())
387                     .unwrap_or(&rel_display);
