401                 .map_err(|_| response_channel_closed("sending find result"))?;
402             sent += 1;
403             Ok(())
404         };
405 
406     let metadata = start_abs
407         .metadata()
408         .map_err(|err| io_to_status(format!("stat {}", start_abs.display()), err))?;
409 
410     if start_abs.is_file() {
411         maybe_emit(start_rel.clone(), metadata, false)?;
412         return Ok(());
413     }
414 
415     if include_dirs && start_rel != Path::new(".") {
416         maybe_emit(start_rel.clone(), metadata, true)?;
417     }
418 
419     let enumerator = FileEnumerator::new(FileFilter::default());
420     enumerator
421         .enumerate_local_streaming(&start_abs, |entry| {
422             let rel_from_root = if start_rel == Path::new(".") {
423                 entry.relative_path.clone()
424             } else {
425                 let mut combined = start_rel.clone();
426                 if entry.relative_path != Path::new(".") {
427                     combined.push(&entry.relative_path);
428                 }
