use crate::cli::RmArgs;
use blit_core::admin::rm;
use blit_core::endpoints::{parse_endpoint_or_local, Endpoint};
use eyre::{bail, Result};
use serde::Serialize;
use std::io::{self, Write};
use std::path::Path;

// Re-export the helper used by `crate::transfers::mod::run_move`
// so existing call sites stay working without an import update.
pub use blit_core::admin::rm::delete_remote_path;

pub async fn run_rm(args: RmArgs) -> Result<()> {
    let remote = match parse_endpoint_or_local(&args.target) {
        Endpoint::Local(path) => {
            bail!(
                "`blit rm` only supports remote paths (received local path: {})",
                path.display()
            );
        }
        Endpoint::Remote(remote) => remote,
    };

    let (module, rel_path) = rm::extract_module_and_path(&remote)?;

    if rel_path.as_os_str().is_empty() || rel_path == Path::new(".") {
        bail!(
            "refusing to delete entire module '{}'; specify a sub-path",
            module
        );
    }

    let rel_components: Vec<String> = rel_path
        .iter()
        .map(|component| component.to_string_lossy().into_owned())
        .collect();
    let rel_string = rel_components.join("/");
    if rel_string.is_empty() {
        bail!(
            "refusing to delete entire module '{}'; specify a sub-path",
            module
        );
    }

    let module_display = format!("{}:/{}", module, rel_string);
    let endpoint_display = format!("{}:{}", remote.host, remote.port);

    if !args.yes {
        print!("Delete {} on {}? [y/N]: ", module_display, endpoint_display);
        io::stdout().flush()?;
        let mut input = String::new();
        io::stdin().read_line(&mut input)?;
        let decision = input.trim().to_ascii_lowercase();
        if !(decision == "y" || decision == "yes") {
            println!("Aborted.");
            return Ok(());
        }
    }

    let entries_deleted = rm::purge(&remote, module.clone(), vec![rel_string.clone()]).await?;

    if args.json {
        #[derive(Serialize)]
        struct RmResult {
            path: String,
            host: String,
            port: u16,
            entries_deleted: u64,
        }
        let result = RmResult {
            path: rel_string,
            host: remote.host.clone(),
            port: remote.port,
            entries_deleted,
        };
        println!("{}", serde_json::to_string_pretty(&result)?);
    } else {
        match entries_deleted {
            0 => println!(
                "No entries removed for {} on {}; path may already be absent.",
                module_display, endpoint_display
            ),
            1 => println!("Deleted {} on {}.", module_display, endpoint_display),
            count => println!(
                "Deleted {} entries under {} on {}.",
                count, module_display, endpoint_display
            ),
        };
    }

    Ok(())
}

//! `rm` — purge a path on a remote daemon.
//!
//! Moved from `crates/blit-cli/src/rm.rs` in A.0. The interactive
//! confirmation prompt and JSON / text formatters stay in `blit-cli`
//! (presentation). The CLI's `move` verb also consumes the
//! `delete_remote_path` helper for its source-side removal step.

use crate::generated::PurgeRequest;
use crate::remote::endpoint::{RemoteEndpoint, RemotePath};
use eyre::{bail, Result};
use std::path::PathBuf;

/// Issue a `Purge` RPC against `remote` for the given `module` and
/// `paths_to_delete`. Returns the count the daemon reports.
/// Caller handles confirmation prompting and presentation.
pub async fn purge(
    remote: &RemoteEndpoint,
    module: String,
    paths_to_delete: Vec<String>,
) -> Result<u64> {
    let uri = remote.control_plane_uri();
    let mut client = crate::client::connect_with_timeout(uri.clone()).await?;

    let response = client
        .purge(PurgeRequest {
            module,
            paths_to_delete,
        })
        .await
        .map_err(|status| eyre::eyre!(status.message().to_string()))?
        .into_inner();

    Ok(response.files_deleted)
}

/// Convenience wrapper around [`purge`] that derives the module
/// from the `RemoteEndpoint` and accepts a single relative path.
/// Used by `blit move` for its source-side removal step.
pub async fn delete_remote_path(remote: &RemoteEndpoint, rel_path: &str) -> Result<u64> {
    let (module, _) = extract_module_and_path(remote)?;
    purge(remote, module, vec![rel_path.to_string()]).await
}

/// Pull the (module, rel_path) pair out of a `RemoteEndpoint`,
/// rejecting bare-host (`Discovery`) variants with an rm-specific
/// error message. Pub so the CLI's interactive `rm` handler can
/// share the same validation.
pub fn extract_module_and_path(remote: &RemoteEndpoint) -> Result<(String, PathBuf)> {
    match &remote.path {
        RemotePath::Module { module, rel_path } => Ok((module.clone(), rel_path.clone())),
        RemotePath::Root { rel_path } => Ok((String::new(), rel_path.clone())),
        RemotePath::Discovery => {
            bail!("remote removal requires module syntax (e.g., server:/module/path)")
        }
    }
}

use crate::cli::FindArgs;
use blit_core::admin::find::{self, FindEntry, FindParams};
use blit_core::endpoints::{
    module_and_rel_path, parse_endpoint_or_local, rel_path_to_string, Endpoint,
};
use eyre::{bail, Result};

pub async fn run_find(args: FindArgs) -> Result<()> {
    let remote = match parse_endpoint_or_local(&args.target) {
        Endpoint::Local(path) => {
            bail!(
                "`blit find` requires a remote path (received local path: {})",
                path.display()
            );
        }
        Endpoint::Remote(remote) => remote,
    };

    let (module, rel_path) = module_and_rel_path(&remote)?;
    let include_files = if args.files || args.dirs {
        args.files
    } else {
        true
    };
    let include_dirs = if args.files || args.dirs {
        args.dirs
    } else {
        true
    };

    let params = FindParams {
        module,
        start_path: rel_path_to_string(&rel_path),
        pattern: args.pattern.unwrap_or_default(),
        case_sensitive: !args.case_insensitive,
        include_files,
        include_directories: include_dirs,
        max_results: args.limit.unwrap_or(0),
    };

    if args.json {
        let mut rows: Vec<FindEntry> = Vec::new();
        find::stream(&remote, params, |entry| {
            rows.push(entry);
            Ok(())
        })
        .await?;
        println!("{}", serde_json::to_string_pretty(&rows)?);
    } else {
        println!("{:<48} {:>12} {:<5}", "PATH", "BYTES", "TYPE");
        find::stream(&remote, params, |entry| {
            let ty = if entry.is_dir { "dir" } else { "file" };
            let size = if entry.is_dir {
                "-".to_string()
            } else {
                entry.size.to_string()
            };
            println!("{:<48} {:>12} {:<5}", entry.path, size, ty);
            Ok(())
        })
        .await?;
    }

    Ok(())
}


