713 /// cr-g3fix4-1: the identity of the entry `path` names — the entry itself,
714 /// never a reparse point's target — and how many names it has. On Windows
715 /// the volume serial number and the file index, and `nNumberOfLinks`, from
716 /// `GetFileInformationByHandle`, on a handle `CreateFileW` opens (through
717 /// std's `OpenOptions`) with `FILE_FLAG_OPEN_REPARSE_POINT` (the entry, not
718 /// its target) and `FILE_FLAG_BACKUP_SEMANTICS` (a directory opens too),
719 /// asking no access rights — std's own `symlink_metadata` opens it the same
720 /// way. std offers no stable identity there (`MetadataExt::file_index` is
721 /// unstable).
722 #[cfg(windows)]
723 pub(crate) fn entry_identity(path: &Path) -> Option<((u64, u64), u64)> {
724     use std::os::windows::fs::OpenOptionsExt;
725     use std::os::windows::io::AsRawHandle;
726     use windows::Win32::Foundation::HANDLE;
727     use windows::Win32::Storage::FileSystem::{
728         GetFileInformationByHandle, BY_HANDLE_FILE_INFORMATION, FILE_FLAG_BACKUP_SEMANTICS,
729         FILE_FLAG_OPEN_REPARSE_POINT,
730     };
731     let file = std::fs::OpenOptions::new()
732         .access_mode(0)
733         .custom_flags(FILE_FLAG_OPEN_REPARSE_POINT.0 | FILE_FLAG_BACKUP_SEMANTICS.0)
734         .open(path)
735         .ok()?;
736     let mut info = BY_HANDLE_FILE_INFORMATION::default();
737     // SAFETY: `file` keeps the handle open for the call, and `info` is a
738     // valid, writable BY_HANDLE_FILE_INFORMATION.
739     unsafe { GetFileInformationByHandle(HANDLE(file.as_raw_handle()), &mut info) }.ok()?;
740     let index = (u64::from(info.nFileIndexHigh) << 32) | u64::from(info.nFileIndexLow);
741     Some((
742         (u64::from(info.dwVolumeSerialNumber), index),
743         u64::from(info.nNumberOfLinks),
744     ))
745 }
